int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->p_type = get_bits(gb, 2);
    ctx->time_increment = get_bits(gb, 16);
    ctx->vop_time_increment = get_bits(gb, 16);
    ctx->vop_structure = get_bits(gb, 2);
    ctx->interlaced = get_bits1(gb);
    ctx->top_field_first = get_bits1(gb);
    ctx->alternate_scan = get_bits1(gb);
    ctx->obmc_disable = get_bits1(gb);
    ctx->sprite_enable = get_bits1(gb);
    ctx->sprite_warping = get_bits1(gb);
    ctx->quant_type = get_bits1(gb);
    ctx->quarter_sample = get_bits1(gb);
    ctx->data_partitioned = get_bits1(gb);
    ctx->reversible_vlc = get_bits1(gb);
    ctx->reduced_resolution = get_bits1(gb);

    skip_bits(gb, 16);  // Skip temporal reference

    if (ctx->p_type == 0) {
        ctx->predictor_reset();
    }

    if (ctx->alternate_scan) {
        for (int i = 0; i < 64; i++) {
            ctx->scan_table[i] = get_bits(gb, 6);
        }
    }

    ctx->load_default_matrices();

    if (ctx->user_data_present) {
        while (get_bits_left(gb) > 0) {
            ctx->process_user_data();
        }
    }

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->frame_type = get_bits1(gb);
    ctx->intra_dct = get_bits1(gb);

    skip_bits(gb, 2); // temporal reference
    skip_bits1(gb);    // VOP structure

    ctx->picture_type = get_bits(gb, 2);

    if (ctx->picture_type == 0) {
        ctx->pred_type = 0;
        ctx->default_matrices = 1;
    } else {
        ctx->pred_type = get_bits1(gb);
    }

    if (ctx->intra_dct) {
        for (int i = 0; i < 64; i++)
            ctx->scantable[i] = i;
    } else {
        for (int i = 0; i < 64; i++)
            ctx->scantable[i] = zig_zag_reorder[i];
    }

    if (ctx->default_matrices) {
        for (int i = 0; i < 6; i++)
            memcpy(ctx->matrix[i], default_matrix[i], sizeof(int) * 64);
    }

    skip_bits(gb, 16); // user data

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->pict_type = get_bits1(gb);
    ctx->time_increment_resolution = 0;
    ctx->vop_time_increment = 0;
    ctx->vop_coding_type = get_bits(gb, 2);
    skip_bits(gb, 1);

    if (ctx->vop_coding_type == 0) {
        ctx->pict_type = FF_I_TYPE;
        skip_bits(gb, 1);
    } else if (ctx->vop_coding_type == 1) {
        ctx->pict_type = FF_P_TYPE;
        skip_bits(gb, 1);
    } else if (ctx->vop_coding_type == 2) {
        ctx->pict_type = FF_B_TYPE;
    } else {
        ctx->pict_type = FF_S_TYPE;
        skip_bits(gb, 1);
    }

    skip_bits(gb, 1);
    ctx->quarter_sample = get_bits1(gb);
    ctx->unrestricted_vector = get_bits1(gb);
    ctx->resync_marker = get_bits1(gb);
    skip_bits(gb, 1);

    if (get_bits1(gb))
        skip_bits(gb, 16);

    ctx->load_intra_quantizer_matrix = get_bits1(gb);
    ctx->load_inter_quantizer_matrix = get_bits1(gb);

    for (int i = 0; i < 64; i++) {
        if (ctx->load_intra_quantizer_matrix)
            ctx->intra_quantizer_matrix[i] = get_bits(gb, 8);
        if (ctx->load_inter_quantizer_matrix)
            ctx->inter_quantizer_matrix[i] = get_bits(gb, 8);
    }

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->frame_type = get_bits1(gb);
    ctx->dct_type = get_bits1(gb);

    skip_bits(gb, 3); // temporal reference
    skip_bits(gb, 1); // VOP structure

    int picture_type = get_bits(gb, 2);

    if (picture_type == P_TYPE) {
        ctx->predictor_reset();
        ctx->scanning_table = default_scanning_table;
    }

    load_default_matrices(ctx);

    skip_bits(gb, 8); // user data

    return 0;
}

int decode_studio_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->current_picture_ptr = NULL;
    ctx->frame_type = 0;
    ctx->inter_dct = 0;

    skip_bits(gb, 8);
    skip_bits(gb, 4);
    skip_bits(gb, 1);

    int temporal_ref = get_bits(gb, 8);
    int vop_structure = get_bits(gb, 1);
    int picture_type = get_bits(gb, 2);

    if (picture_type == 1) {
        ctx->reset_predictor = 1;
        ctx->scantable = default_scantable;
    }

    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            ctx->matrix[i][j] = get_bits(gb, 8);
        }
    }

    return 0;
}
